def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n == 1:
        return 0
    max_divisor = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            if i < max_divisor:
                max_divisor = i
            other = n // i
            if other < max_divisor:
                max_divisor = other
    return max_divisor

