        return x
    else:
        return y

def double_the_difference(lst):
    total = 0
    for num in lst:
        if type(num) is int and num % 2 != 0:
            total += num ** 2
    return total

def even_odd_count(num):
    num = abs(num)
    even_count = 0
    odd_count = 0
    for digit in str(num):
        digit_int = int(digit)
        if digit_int % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def int_to_mini_roman(number):
    roman_numerals = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'x'), (40, 'xx'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'),
        (1, 'i')
    ]
    result = ''
    for value, symbol in roman_numerals:
        while number >= value:
            result += symbol
            number -= value
    return result

def right_angle_triangle(a, b, c):
    a, b, c = sorted([a, b, c])
    return a ** 2 + b ** 2 == c ** 2

def eat(number, need, remaining):
    total = number + need
    if total > remaining:
        total = remaining
    return [total, remaining - total]

def do_algebra(operator, operand):
    def evaluate_expression(ops, operands):
        stack = []
        for op, num in zip(ops, operands):
            if op == '+':
                stack.append(stack.pop() + num)
            elif op == '-':
                stack.append(stack.pop() - num)
            elif op == '*':
                stack.append(stack.pop() * num)
            elif op == '/':
                stack.append(stack.pop() // num)
            elif op == '**':
                stack.append(stack.pop() ** num)
        return stack[0]

    return evaluate_expression(operator, operand)

def solve(s):
    result = []
    for c in s:
        if c.isalpha():
            result.append(c.swapcase())
        else:
            result.append(c)
    return ''.join(result)

import hashlib

def string_to_md5(text):
    if not text:
        return None
    md5_hash = hashlib.md5(text.encode('utf-8')).hexdigest()
    return md5_hash
